using System.Globalization;
using System.Text;
using UploadGuard.Tests;

namespace UploadGuard.Benchmarks;

/// <summary>
/// Prints a Markdown table: which library lets each file through, and why. Run with <c>--compare</c>.
/// Every file is generated by tests/UploadGuard.Tests/Samples.cs, so anyone can reproduce the table.
/// </summary>
internal static class Comparison
{
    private static readonly (string Case, byte[] Data, string Name, bool ShouldAccept)[] Cases =
    [
        ("JPEG photo", Samples.Jpeg(), "photo.jpg", true),
        ("Word document", Samples.All[FileTypes.Docx].Data, "letter.docx", true),
        ("CSV export", Samples.All[FileTypes.Csv].Data, "export.csv", true),
        ("JPEG with PHP appended", Samples.Concat(Samples.Jpeg(), Samples.Utf8("<?php echo 1; ?>")), "photo.jpg", false),
        ("GIF/HTML polyglot", Samples.Concat(Samples.Utf8("GIF89a"), [1, 0, 1, 0], Samples.Utf8("<script src=//x></script>")), "funny.gif", false),
        ("PNG with `<script>` appended", Samples.Concat(Samples.Png(), Samples.Utf8("<script>alert(1)</script>")), "image.png", false),
        ("Macro-enabled Word renamed .docx", Samples.All[FileTypes.Docm].Data, "invoice.docx", false),
        ("ZIP bomb (20 MB of zeros)", Samples.Zip(("zeros.bin", new byte[20_000_000])), "bomb.zip", false),
        ("ZIP slip (`../` entry)", Samples.Zip(("../../evil.sh", Samples.Utf8("x"))), "photos.zip", false),
        ("PDF with JavaScript", Samples.Pdf("1 0 obj <</OpenAction <</S /JavaScript /JS (app.alert(1))>>>> endobj"), "invoice.pdf", false),
        ("PDF with JavaScript in an object stream", Samples.PdfWithCompressedObject("1 0 <</OpenAction <</S /JavaScript /JS (app.alert(1))>>>>"), "invoice.pdf", false),
        ("SVG with `<script>`", Samples.Utf8(Samples.Svg("<script>alert(1)</script>")), "logo.svg", false),
        ("HTML page named .csv", Samples.Utf8("<html><script>alert(1)</script></html>"), "export.csv", false),
        ("File name `shell.php.jpg`", Samples.Jpeg(), "shell.php.jpg", false),
    ];

    public static void Print()
    {
        var table = new StringBuilder();
        table.AppendLine("| File | Expected | Mime-Detective 25.8.1 | File.TypeChecker 4.4.0 | UploadGuard |");
        table.AppendLine("|---|---|---|---|---|");
        int[] correct = [0, 0, 0];
        foreach (var (name, data, fileName, shouldAccept) in Cases)
        {
            (bool Accepted, string? Detected)[] verdicts =
            [
                Detectors.MimeDetective(data, fileName),
                Detectors.FileTypeChecker(data, fileName),
                Detectors.UploadGuard(data, fileName),
            ];

            table.Append(CultureInfo.InvariantCulture, $"| {name} | {(shouldAccept ? "accept" : "reject")} |");
            for (var i = 0; i < verdicts.Length; i++)
            {
                var (accepted, detected) = verdicts[i];
                var right = accepted == shouldAccept;
                correct[i] += right ? 1 : 0;
                var why = i == 2 && !accepted ? detected : detected is null ? "not recognized" : $"detected {detected}";
                table.Append(CultureInfo.InvariantCulture, $" {(right ? "✅" : "❌")} {(accepted ? "accepted" : "rejected")} ({why}) |");
            }

            table.AppendLine();
        }

        table.AppendLine(CultureInfo.InvariantCulture, $"| **Correct** | | **{correct[0]}/{Cases.Length}** | **{correct[1]}/{Cases.Length}** | **{correct[2]}/{Cases.Length}** |");
        Console.OutputEncoding = Encoding.UTF8;
        Console.Write(table);
    }
}
